// Command regencli regenerates every generated cobra command package from the
// annotated unified OpenAPI spec, plus the RegisterAll wiring.
//
// Commands are grouped by API service (x-flexera-service): each (service, tag)
// pair is generated by ./cmd/gencli into
// internal/commands/<service>/<tag>/cmd_gen.go, stale packages are pruned, and
// internal/commands/register_gen.go registers one top-level command per
// service with its tags beneath it:
//
//	flexera-cli <service> <tag> <operation>
//
// Usage:
//
//	go run ./cmd/regencli
//
// Invoked transitively by `go generate ./...` via the //go:generate
// directive in cli/flexera-cli/generate.go.
package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"go/format"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

const (
	specPath    = "unified-openapi/openapi3.json"
	commandsDir = "internal/commands"
	modulePath  = "github.com/flexera-public/flexera-cli"
)

type genTag struct {
	Tag     string // OpenAPI tag
	Service string // x-flexera-service id ("" in focused tests)
	Pkg     string // directory relative to internal/commands; base is the Go package name
	Cmd     string // provisional tag command name emitted by gencli
	// Path is the final command path of the tag command (service first).
	// Empty means the tag command is registered at the root as Cmd.
	Path  []string
	Group *serviceGroup
}

func (t genTag) finalPath() []string {
	if len(t.Path) == 0 {
		return []string{t.Cmd}
	}
	return t.Path
}

// importAlias is the identifier used for the package in register_gen.go.
func (t genTag) importAlias() string { return strings.ReplaceAll(t.Pkg, "/", "") }

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "regencli:", err)
		os.Exit(1)
	}
}

func run() error {
	wd, err := os.Getwd()
	if err != nil {
		return err
	}
	if filepath.Base(wd) != "flexera-cli" {
		return fmt.Errorf("regencli must run from cli/flexera-cli (cwd: %s)", wd)
	}

	specData, err := os.ReadFile(specPath)
	if err != nil {
		return err
	}
	tags, err := planTags(specData)
	if err != nil {
		return err
	}
	fmt.Fprintf(os.Stderr, "regencli: %d service/tag packages planned\n", len(tags))
	return regenerate(commandsDir, tags, generationHooks{
		generate: generateTag,
		verify:   verifyGenerated,
		rename:   os.Rename,
		prepare:  preparePublication,
	})
}

// Hooks keep failure tests independent of subprocesses and the real SDK.
type generationHooks struct {
	generate func(genTag, string) error
	verify   func(string, []genTag) error
	rename   func(string, string) error
	prepare  func(string, []genTag) ([]publicationArtifact, error)
}

func generateTag(tag genTag, out string) error {
	c := exec.Command("go", "run", "./cmd/gencli",
		"-spec", specPath, "-tag", tag.Tag, "-pkg", path.Base(tag.Pkg), "-cmd", tag.Cmd, "-out", out, "-metadata", filepath.Join(filepath.Dir(out), "metadata.json"),
		"-service", tag.Service, "-exclude", strings.Join(curatedOperationIDs(), ","))
	c.Stderr = os.Stderr
	return c.Run()
}

func regenerate(destination string, tags []genTag, hooks generationHooks) (err error) {
	parent := filepath.Dir(destination)
	if err := os.MkdirAll(parent, 0o755); err != nil {
		return err
	}
	// A sibling staging directory ensures publication stays on one filesystem.
	stage, err := os.MkdirTemp(parent, ".commands-stage-")
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, os.RemoveAll(stage)) }()
	// MkdirTemp defaults to 0700; published commands retain the usual mode.
	if err := os.Chmod(stage, 0o755); err != nil {
		return err
	}

	var generated []genTag
	for _, t := range tags {
		out := filepath.Join(stage, filepath.FromSlash(t.Pkg), "cmd_gen.go")
		if err := hooks.generate(t, out); err != nil {
			return fmt.Errorf("generate %s tag %q: %w", t.Service, t.Tag, err)
		}
		generated = append(generated, t)
	}

	if err := hooks.verify(stage, generated); err != nil {
		return err
	}
	if err := writeRegister(stage, generated); err != nil {
		return fmt.Errorf("write staged registration: %w", err)
	}
	if err := rewriteStagedHelp(stage, generated); err != nil {
		return err
	}
	if hooks.prepare != nil {
		artifacts, err := hooks.prepare(stage, generated)
		if err != nil {
			return err
		}
		defer func() {
			for _, artifact := range artifacts {
				err = errors.Join(err, os.RemoveAll(artifact.Staged))
			}
		}()
		artifacts = append([]publicationArtifact{{Staged: stage, Destination: destination}}, artifacts...)
		return publishArtifacts(artifacts, hooks.rename)
	}
	if err := publish(stage, destination, hooks.rename); err != nil {
		return err
	}
	fmt.Fprintf(os.Stderr, "regencli: wrote %d generated tag packages\n", len(generated))
	return nil
}

func preparePublication(stage string, tags []genTag) (artifacts []publicationArtifact, err error) {
	defer func() {
		if err != nil {
			for _, artifact := range artifacts {
				_ = os.RemoveAll(artifact.Staged)
			}
		}
	}()
	specData, err := os.ReadFile(specPath)
	if err != nil {
		return nil, err
	}
	curated, err := curatedEntries(specData)
	if err != nil {
		return nil, err
	}
	data, err := buildCatalog(stage, tags, specData, curated...)
	if err != nil {
		return nil, err
	}
	if len(data) > 5*1024*1024 {
		return nil, fmt.Errorf("catalog size %d exceeds the approved 5 MiB budget", len(data))
	}
	second, err := buildCatalog(stage, tags, specData, curated...)
	if err != nil {
		return nil, err
	}
	if string(data) != string(second) {
		return nil, fmt.Errorf("catalog generation is nondeterministic")
	}
	report, err := verifyCoverage(specData, data)
	if err != nil {
		return nil, err
	}
	fmt.Fprintf(os.Stderr, "regencli: catalog %d bytes, %d exact curated operations\n", len(data), len(curated))
	if err := auditStagedTree(stage, data); err != nil {
		return nil, err
	}
	for _, tag := range tags {
		if err := os.Remove(filepath.Join(stage, filepath.FromSlash(tag.Pkg), "metadata.json")); err != nil {
			return nil, err
		}
	}
	for _, item := range []struct {
		name, destination string
		data              []byte
	}{{"catalog_gen.json", "internal/catalog/catalog_gen.json", data}, {"coverage_gen.json", "internal/catalog/coverage_gen.json", report}} {
		// Files are staged beside the commands tree; publication uses sibling
		// backups and rollback for all destinations as one transaction.
		path := filepath.Join(stage, item.name)
		if err := os.WriteFile(path, item.data, 0o644); err != nil {
			return nil, err
		}
		// Keep publication sources outside the directory renamed first.
		file, err := os.CreateTemp(filepath.Dir(stage), ".catalog-stage-*")
		if err != nil {
			return nil, err
		}
		name := file.Name()
		artifacts = append(artifacts, publicationArtifact{Staged: name, Destination: item.destination})
		if err := file.Close(); err != nil {
			return nil, err
		}
		if err := os.Rename(path, name); err != nil {
			return nil, err
		}
	}
	return artifacts, nil
}

// publish replaces the entire tree (including registration), pruning stale
// packages only after generation and verification succeed. If restoration also
// fails, preserve the backup and report its location for manual recovery.
func publish(stage, destination string, rename func(string, string) error) (err error) {
	if _, err := os.Lstat(destination); errors.Is(err, os.ErrNotExist) {
		return rename(stage, destination)
	} else if err != nil {
		return err
	}
	backupDir, err := os.MkdirTemp(filepath.Dir(destination), ".commands-backup-")
	if err != nil {
		return err
	}
	backup := filepath.Join(backupDir, "commands")
	keepBackup := false
	defer func() {
		if !keepBackup {
			err = errors.Join(err, os.RemoveAll(backupDir))
		}
	}()
	if err := rename(destination, backup); err != nil {
		return fmt.Errorf("backup generated commands: %w", err)
	}
	if err := rename(stage, destination); err != nil {
		if rollbackErr := rename(backup, destination); rollbackErr != nil {
			keepBackup = true
			return errors.Join(fmt.Errorf("publish generated commands: %w", err),
				fmt.Errorf("rollback failed; old commands preserved at %s: %w", backup, rollbackErr))
		}
		return fmt.Errorf("publish generated commands (rolled back): %w", err)
	}
	return nil
}

// verifyGenerated type-checks every flexera.* / client.* symbol referenced
// by the freshly generated command files against the real unified-go-client
// package (loaded once via go/packages + go/types). This turns a spec/client
// naming drift (e.g. an operationId or generated type renamed upstream)
// into a hard regen-time failure instead of a downstream `go build` error —
// or worse, a silent mismatch that only trips at runtime.
func verifyGenerated(directory string, tags []genTag) error {
	sv, err := newSymbolVerifier()
	if err != nil {
		return err
	}
	return verifyFiles(sv, directory, tags)
}

func verifyFiles(sv *symbolVerifier, directory string, tags []genTag) error {
	var issues []string
	for _, t := range tags {
		out := filepath.Join(directory, filepath.FromSlash(t.Pkg), "cmd_gen.go")
		issues = append(issues, sv.verifyFile(out)...)
	}
	if len(issues) > 0 {
		return fmt.Errorf("symbol verification against unified-go-client failed (%d mismatch(es)):\n%s", len(issues), strings.Join(issues, "\n"))
	}
	fmt.Fprintf(os.Stderr, "regencli: verified %d generated file(s) against unified-go-client symbols\n", len(tags))
	return nil
}

type spec struct {
	Paths      map[string]map[string]json.RawMessage `json:"paths"`
	Components struct {
		Schemas map[string]json.RawMessage `json:"schemas"`
	} `json:"components"`
}

// writeRegister emits register_gen.go: one top-level command per service
// (or per tag when a tag has no service group, as in focused tests), with
// tag commands nested along their final Path.
func writeRegister(directory string, tags []genTag) error {
	type node struct {
		use      string
		tag      *genTag
		group    *serviceGroup
		children map[string]*node
	}
	root := &node{children: map[string]*node{}}
	aliases := map[string]string{}
	for i := range tags {
		t := &tags[i]
		alias := t.importAlias()
		if other, dup := aliases[alias]; dup {
			return fmt.Errorf("import alias %q shared by %s and %s", alias, other, t.Pkg)
		}
		aliases[alias] = t.Pkg
		current := root
		for depth, use := range t.finalPath() {
			child := current.children[use]
			if child == nil {
				child = &node{use: use, children: map[string]*node{}}
				current.children[use] = child
			}
			if depth == 0 && t.Group != nil {
				child.group = t.Group
			}
			current = child
		}
		if current.tag != nil {
			return fmt.Errorf("tags %q and %q share command path %v", current.tag.Tag, t.Tag, t.finalPath())
		}
		current.tag = t
	}

	sortedChildren := func(n *node) []*node {
		out := make([]*node, 0, len(n.children))
		for _, c := range n.children {
			out = append(out, c)
		}
		sort.Slice(out, func(i, j int) bool { return out[i].use < out[j].use })
		return out
	}
	var expr func(n *node, indent string) (string, error)
	expr = func(n *node, indent string) (string, error) {
		var base string
		switch {
		case n.tag != nil:
			base = n.tag.importAlias() + ".NewCmd()"
			if n.use != n.tag.Cmd {
				base = fmt.Sprintf("nest(%s, %q)", base, n.use)
			}
		case n.group != nil:
			base = fmt.Sprintf("&cobra.Command{Use: %q}", n.use)
		default:
			return "", fmt.Errorf("command %q has neither a tag nor a service group", n.use)
		}
		if g := n.group; g != nil {
			base = fmt.Sprintf("service(%s, %q, %#v, %q, %q)", base, g.Cmd, g.Aliases, g.Short, g.Long)
			base = strings.Replace(base, "[]string(nil)", "nil", 1)
		}
		children := sortedChildren(n)
		if len(children) == 0 {
			return base, nil
		}
		var b strings.Builder
		fmt.Fprintf(&b, "withChildren(%s,\n", base)
		for _, c := range children {
			e, err := expr(c, indent+"\t")
			if err != nil {
				return "", err
			}
			fmt.Fprintf(&b, "%s\t%s,\n", indent, e)
		}
		fmt.Fprintf(&b, "%s)", indent)
		return b.String(), nil
	}

	sorted := append([]genTag(nil), tags...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Pkg < sorted[j].Pkg })
	var b strings.Builder
	b.WriteString("// Code generated by cmd/regencli. DO NOT EDIT.\n\n")
	b.WriteString("package commands\n\n")
	b.WriteString("import (\n")
	b.WriteString("\t\"github.com/spf13/cobra\"\n\n")
	for _, t := range sorted {
		fmt.Fprintf(&b, "\t%s %q\n", t.importAlias(), modulePath+"/"+commandsDir+"/"+t.Pkg)
	}
	b.WriteString(")\n\n")
	b.WriteString("// RegisterAll adds one command per API service to root; each service\n")
	b.WriteString("// command holds that service's generated tag commands.\n")
	b.WriteString("func RegisterAll(root *cobra.Command) {\n")
	b.WriteString("\troot.AddCommand(\n")
	for _, n := range sortedChildren(root) {
		e, err := expr(n, "\t\t")
		if err != nil {
			return err
		}
		fmt.Fprintf(&b, "\t\t%s,\n", e)
	}
	b.WriteString("\t)\n}\n")
	b.WriteString(registerHelpers)
	formatted, err := format.Source([]byte(b.String()))
	if err != nil {
		return fmt.Errorf("format register_gen.go: %w", err)
	}
	return os.WriteFile(filepath.Join(directory, "register_gen.go"), formatted, 0o644)
}

const registerHelpers = `
// service presents c as the top-level command for one API service.
func service(c *cobra.Command, use string, aliases []string, short, long string) *cobra.Command {
	c.Use, c.Aliases, c.Short, c.Long = use, aliases, short, long
	return c
}

// nest renames a tag command that is registered beneath a sibling tag.
func nest(c *cobra.Command, use string) *cobra.Command {
	c.Use = use
	return c
}

func withChildren(c *cobra.Command, children ...*cobra.Command) *cobra.Command {
	c.AddCommand(children...)
	return c
}
`

// cleanIdent turns a tag into a PascalCase alphanumeric identifier
// ("API Event" -> "APIEvent", "Bill Connect AWS" -> "BillConnectAWS").
func cleanIdent(t string) string {
	tmp := strings.Map(func(r rune) rune {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') {
			return r
		}
		return ' '
	}, t)
	parts := strings.Fields(tmp)
	for i, p := range parts {
		parts[i] = strings.ToUpper(p[:1]) + p[1:]
	}
	return strings.Join(parts, "")
}

// uniquePkg lowercases ident into a Go package name, ensuring uniqueness and
// a non-digit first rune.
func uniquePkg(ident string, used map[string]bool) string {
	base := strings.ToLower(ident)
	if base == "" {
		base = "tag"
	}
	if base[0] >= '0' && base[0] <= '9' {
		base = "t" + base
	}
	pkg := base
	for n := 2; used[pkg]; n++ {
		pkg = fmt.Sprintf("%s%d", base, n)
	}
	used[pkg] = true
	return pkg
}

func kebab(s string) string {
	runes := []rune(s)
	var b strings.Builder
	for i, r := range runes {
		isUpper := r >= 'A' && r <= 'Z'
		if i > 0 && isUpper {
			prev := runes[i-1]
			prevUpper := prev >= 'A' && prev <= 'Z'
			nextLower := i+1 < len(runes) && runes[i+1] >= 'a' && runes[i+1] <= 'z'
			if !prevUpper || (prevUpper && nextLower) {
				b.WriteByte('-')
			}
		}
		if isUpper {
			b.WriteRune(r + 32)
		} else {
			b.WriteRune(r)
		}
	}
	return b.String()
}
